/* Reverse of the above function */
static int wcscmp_rstar(const wchar_t *__restrict__ a, const wchar_t *__restrict__ b)
{
    const wchar_t *oa = a, *ob=b;
    if(!b) return 0;

    while(*a++) ;
    a--;
    while(*b++) ;
    b--;
    if(*ob != '*' && a-oa != b-ob)
        return 1;

    while(a > oa && b > ob && *a == *b) { a--; b--; }

    return (*a != *b) & (*b != '*');
}


